arguments.command:
python3 -c "
import sys; sys.path.insert(0, '.')
import parse

tests = [
    ('{a}', True),
    ('{a}b', True),
    ('{a}{b}', True),
    ('{{a}}', True),
    ('{a b}', True),
    ('{a', False),  # unclosed
    ('a}', False),  # unmatched close
    ('{} {}', True),
    ('foo{bar}baz', True),
]

for fmt, should_pass in tests:
    try:
        p = parse.Parser(fmt)
        if should_pass:
            print(f'OK: {fmt!r}')
        else:
            print(f'FAIL (should have raised error): {fmt!r}')
    except Exception as e:
        if not should_pass:
            print(f'OK (raised error): {fmt!r} -> {e}')
        else:
            print(f'FAIL (unexpected error): {fmt!r} -> {e}')
" 2>&1 | grep -v SyntaxWarning
